-- RPCs seguras. Requiere proveedor facial externo antes de insertar attendance_events.
begin;
do $$ begin if not exists(select 1 from public.app_sql_versions where version=20) then raise exception 'Apply 020 first'; end if; if exists(select 1 from public.app_sql_versions where version=21) then raise exception 'SQL 021 already applied'; end if; end $$;
create or replace function public.attendance_lookup_self(p_document_type text,p_document text) returns jsonb language plpgsql security definer set search_path=public as $$ declare r jsonb; begin select jsonb_build_object('name',p.nombres||' '||p.apellidos,'maskedDocument',left(p.documento,2)||'****','stores',coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.nombre)),'[]'::jsonb),'nextEvent','entrada') into r from user_profiles u join personas p on p.id=u.persona_id left join tienda_supervisores ts on ts.user_id=u.user_id and ts.valid_to is null left join tiendas t on t.id=ts.tienda_id and t.is_active where u.user_id=auth.uid() and u.role='supervisor' and u.is_active and p.documento=p_document group by p.nombres,p.apellidos,p.documento; return r; end $$;
create or replace function public.attendance_begin_attempt(p_store_id uuid,p_idempotency_key uuid,p_latitude numeric,p_longitude numeric,p_accuracy_meters numeric) returns jsonb language plpgsql security definer set search_path=public as $$ declare result jsonb; begin if not exists(select 1 from user_profiles where user_id=auth.uid() and role='supervisor' and is_active) then raise exception 'SUPERVISOR_REQUIRED'; end if; if not exists(select 1 from tienda_supervisores where tienda_id=p_store_id and user_id=auth.uid() and valid_to is null) then raise exception 'STORE_NOT_AUTHORIZED'; end if; if p_accuracy_meters>100 then raise exception 'GPS_IMPRECISE'; end if; insert into attendance_attempts(user_id,tienda_id,idempotency_key) values(auth.uid(),p_store_id,p_idempotency_key) on conflict(idempotency_key) do update set idempotency_key=excluded.idempotency_key returning jsonb_build_object('id',id,'status','face_validation_required') into strict result; return result; end $$;
revoke all on function public.attendance_lookup_self(text,text) from public; revoke all on function public.attendance_begin_attempt(uuid,uuid,numeric,numeric,numeric) from public; grant execute on function public.attendance_lookup_self(text,text),public.attendance_begin_attempt(uuid,uuid,numeric,numeric,numeric) to authenticated;
insert into public.app_sql_versions(version,name) values(21,'asistencia_motor');
commit;
